const rows = $input.all().map(i => i.json).filter(r => r && r.orderId);

// Case-insensitive, contains-match on status so small staff typos in casing
// ("On The Way", "ON THE WAY") still match -- exact-match sheet filtering
// would silently miss those.
const isOnTheWay = (r) => String(r.status || '').toLowerCase().includes('on_the_way');
const notYetNotified = (r) => String(r.riderNotified || '').toLowerCase() !== 'true';

const pending = rows.filter(r => isOnTheWay(r) && notYetNotified(r));

// Orders without a jid can't be addressed -- skip them, don't error the whole batch.
const sendable = pending.filter(r => r.jid && String(r.jid).trim());
const skippedNoJid = pending.length - sendable.length;
if (skippedNoJid > 0) {
  console.log('Skipped ' + skippedNoJid + ' order(s) with status on the way but no jid stored.');
}

return sendable.map(r => ({ json: r }));

const items = $input.all().map(i => i.json);

return items.map(row => {
  let orderItems = [];
  try { orderItems = JSON.parse(row.items || '[]'); } catch (e) {}
  const itemLines = orderItems.map(i => (i.name || 'Item') + ' x' + (i.qty || 1)).join(', ');

  const message = 'Assalam o Alaikum! Aap ka order (' + itemLines + ') rider ke pass pohanch gaya hai ' +
    'aur jald hi aapke address par pohanch jayega. Order ID: ' + row.orderId + '.';

  return {
    json: {
      row_number: row.row_number,
      jid: row.jid,
      message: message
    }
  };
});
